SELECT DATE_FORMAT(`create_time`, #{param.dateExp}) AS `time`, COUNT(id) AS `count` FROM maintenance_tasks
and `create_time` BETWEEN #{param.period.begin} and #{param.period.end}
and `maintenance_task_status` = #{status}
GROUP BY DATE_FORMAT(`create_time`, #{param.dateExp}) ORDER BY DATE_FORMAT(`create_time`, #{param.dateExp})

SELECT COUNT(1)
FROM maintenance_tasks



        AND create_time >= #{param.period.begin}



        AND create_time <= #{param.period.end}



        AND plan_id IN

            #{planId}



        AND (

        maintenance_time IS NOT NULL
        AND (

        (maintenance_finish_time IS NOT NULL AND maintenance_finish_time > DATE_ADD(maintenance_time, INTERVAL 48 HOUR))
        OR

        (maintenance_finish_time IS NULL AND NOW() > DATE_ADD(maintenance_time, INTERVAL 48 HOUR))
        )
        )
